#include <cstdio>
#include <cstdint>
#include <cstring>
#include <cmath>
#include <vector>
#include <string>
#include <random>
using namespace std;

static bool ok(float x){
  if (std::isnan(x)||std::isinf(x)) return true;      // printed as nan/inf, stof-safe
  if (x==0.0f) return true;                          // "0" / "-0" safe
  float a = fabsf(x);
  return a >= 1.5e-38f && a <= 3.0e38f;              // avoid subnormal/overflow strings
}
static void emit(vector<float>&v, float r,float g,float b){
  if(!ok(r)||!ok(g)||!ok(b)) return;
  v.push_back(r); v.push_back(g); v.push_back(b);
}
int main(){
  mt19937_64 rng(20260810u);
  vector<float> t;
  auto U=[&](double lo,double hi){ return (float)(lo+(hi-lo)*(double)(rng()>>11)/9007199254740992.0); };

  // 1) canonical / hand-picked
  const float sp[] = {0.0f,-0.0f,1.0f,-1.0f,0.5f,-0.5f,0.25f,0.75f,2.0f,-2.0f,3.0f,
                      1e-7f,-1e-7f,1e-8f,1e-9f,1e-20f,1e20f,1e30f,-1e30f,1e-30f,
                      0.4f,0.2f,0.8f,0.123456789f,0.987654321f,0.333333343f,0.666666687f,
                      1.00000012f,0.99999994f,0.5000001f,0.4999999f,
                      INFINITY,-INFINITY,NAN,
                      16777216.f,16777215.f,-16777216.f,1.17549435e-38f,-1.17549435e-38f};
  int ns = sizeof(sp)/sizeof(sp[0]);
  for(int i=0;i<ns;i++)for(int j=0;j<ns;j++)for(int k=0;k<ns;k++) if(((i*7919+j*104729+k*1299709)%3)==0) emit(t,sp[i],sp[j],sp[k]);

  // 2) all-equal triples (max==min, guard paths)
  for(int i=0;i<ns;i++){ emit(t,sp[i],sp[i],sp[i]); }
  for(int i=0;i<400;i++){ float x=U(-3,3); emit(t,x,x,x); }
  // 2b) sign-of-zero permutations
  const float z[2]={0.0f,-0.0f};
  for(int a=0;a<2;a++)for(int b=0;b<2;b++)for(int c=0;c<2;c++) emit(t,z[a],z[b],z[c]);
  for(int a=0;a<2;a++)for(int b=0;b<2;b++){ float w=U(-2,2);
    emit(t,z[a],z[b],w); emit(t,z[a],w,z[b]); emit(t,w,z[a],z[b]);
    emit(t,z[a],z[b],-fabsf(w)); emit(t,-fabsf(w),z[a],z[b]); emit(t,z[a],-fabsf(w),z[b]); }

  // 3) pairwise ties (each of r==g, g==b, r==b), incl. negatives
  for(int i=0;i<3000;i++){ float x=U(-2,2), y=U(-2,2);
    emit(t,x,x,y); emit(t,x,y,x); emit(t,y,x,x); }
  // 3b) ties with one component zero
  for(int i=0;i<300;i++){ float x=U(-2,2);
    emit(t,x,x,0.0f); emit(t,x,x,-0.0f); emit(t,0.0f,x,x); emit(t,-0.0f,x,x); emit(t,x,0.0f,x); emit(t,x,-0.0f,x); }

  // 4) uniform [0,1]
  for(int i=0;i<9000;i++) emit(t,U(0,1),U(0,1),U(0,1));
  // 5) uniform [-1,2] (out of gamut, negative max, k<0 etc.)
  for(int i=0;i<6000;i++) emit(t,U(-1,2),U(-1,2),U(-1,2));
  // 6) all-negative (max<0 : discriminates ==0 vs <=0 guard)
  for(int i=0;i<3000;i++) emit(t,U(-4,-1e-6),U(-4,-1e-6),U(-4,-1e-6));
  // 6b) max exactly -0.0 with negative others (guard fires on -0.0)
  for(int i=0;i<600;i++){ float a=-fabsf(U(-3,3)), b2=-fabsf(U(-3,3));
    emit(t,-0.0f,a,b2); emit(t,a,-0.0f,b2); emit(t,a,b2,-0.0f);
    emit(t,0.0f,a,b2);  emit(t,a,0.0f,b2);  emit(t,a,b2,0.0f); }
  // 7) max exactly 0 with mixed (delta>0, max==0 -> guard)
  for(int i=0;i<600;i++){ float a=-fabsf(U(-3,3));
    emit(t,0.0f,a,a); emit(t,0.0f,a,0.0f); emit(t,-0.0f,a,0.0f); emit(t,a,0.0f,-0.0f); }
  // 8) tiny magnitudes / huge magnitudes / mixed exponents
  for(int i=0;i<3000;i++){ auto E=[&](){ int e=(int)(rng()%70)-35; float m=U(-1,1); return (float)(m*pow(10.0,e)); };
    emit(t,E(),E(),E()); }
  // 9) near l==0.5 boundary (max+min ~ 1)
  for(int i=0;i<2000;i++){ float mx=U(0.5,1.0); float mn=1.0f-mx; float mid=U(0,1)*(mx-mn)+mn;
    emit(t,mx,mid,mn); emit(t,mn,mx,mid); emit(t,mid,mn,mx); }
  // 10) 8-bit-ish quantised values (typical usage)
  for(int i=0;i<3000;i++){ auto Q=[&](){ return (float)(rng()%256)/255.0f; }; emit(t,Q(),Q(),Q()); }
  // 11) inf/nan mixed with finite
  const float wx[3]={INFINITY,-INFINITY,NAN};
  for(int i=0;i<400;i++){ float a=U(-2,2),b2=U(-2,2); int q=rng()%3;
    emit(t,wx[q],a,b2); emit(t,a,wx[q],b2); emit(t,a,b2,wx[q]);
    emit(t,wx[q],wx[(q+1)%3],b2); emit(t,a,wx[q],wx[(q+2)%3]); emit(t,wx[q],a,wx[q]); }
  // 12) random bit patterns (finite, non-subnormal)
  for(int i=0;i<6000;i++){ auto R=[&](){ for(;;){ uint32_t u=(uint32_t)rng(); float f; memcpy(&f,&u,4);
        if(ok(f)&&!std::isnan(f)&&!std::isinf(f)) return f; } };
    emit(t,R(),R(),R()); }
  // 13) adjacent-ulp neighbours (ties broken by 1 ulp)
  for(int i=0;i<2000;i++){ float x=U(-2,2); if(x==0) x=0.5f;
    float xp=nextafterf(x,INFINITY), xm=nextafterf(x,-INFINITY);
    emit(t,x,xp,xm); emit(t,xm,x,xp); emit(t,xp,xm,x); }

  for(size_t i=0;i+2<t.size();i+=3) printf("%.9g %.9g %.9g\n", t[i],t[i+1],t[i+2]);
  fprintf(stderr,"triples=%zu\n", t.size()/3);
  return 0;
}
