#include <iostream>
#include <string>
#include <cstdio>
#include <algorithm>
#ifndef HVAR
#define HVAR 0
#endif
#ifndef SVAR
#define SVAR 0
#endif
#ifndef VVAR
#define VVAR 0
#endif
static inline float mx3(float r,float g,float b){ return std::max(std::max(r,g),b); }
static inline float mn3(float r,float g,float b){ return std::min(std::min(r,g),b); }

static float hue(float r,float g,float b,float mx,float mn,float d){
#if HVAR==0
  if (mx==mn) return 0.0f;
  else if (mx==r && g>=b) return 60.0f*(g-b)/d;
  else if (mx==r)         return 60.0f*(g-b)/d + 360.0f;
  else if (mx==g)         return 60.0f*(b-r)/d + 120.0f;
  else                    return 60.0f*(r-g)/d + 240.0f;
#elif HVAR==1
  if (mx==mn) return 0.0f;
  else if (mx==r && g>=b) return 60.0f*((g-b)/d);
  else if (mx==r)         return 60.0f*((g-b)/d) + 360.0f;
  else if (mx==g)         return 60.0f*((b-r)/d) + 120.0f;
  else                    return 60.0f*((r-g)/d) + 240.0f;
#elif HVAR==2
  if (mx==mn) return 0.0f;
  else if (mx==r && g>=b) return 60.0f*(g-b)/d;
  else if (mx==r)         return 60.0f*((g-b)/d + 6.0f);
  else if (mx==g)         return 60.0f*((b-r)/d + 2.0f);
  else                    return 60.0f*((r-g)/d + 4.0f);
#endif
}
int main(int argc,char**argv){
  float r=0.4f,g=0.2f,b=0.8f;
  if(argc>3){ r=std::stof(argv[1]); g=std::stof(argv[2]); b=std::stof(argv[3]); }
  float mx=mx3(r,g,b), mn=mn3(r,g,b), d=mx-mn;
  float h=hue(r,g,b,mx,mn,d);
  // HSL
  float sl_l=(mx+mn)/2.0f, sl_s;
  if(mx==mn) sl_s=0.0f; else if(sl_l<0.5f) sl_s=d/(mx+mn); else sl_s=d/(2.0f-mx-mn);
  // HSV
#if VVAR==0
  float sv_v=mx;
#elif VVAR==1
  double sv_v=(double)mx;
#elif VVAR==2
  float sv_v=mn+d;
#endif
  float sv_s;
#if SVAR==0
  sv_s = (mx==0.0f)?0.0f:(d/mx);
#elif SVAR==1
  sv_s = (mx<=0.0f)?0.0f:(d/mx);
#elif SVAR==2
  sv_s = (mx==0.0f)?d:(d/mx);
#elif SVAR==3
  sv_s = (d==0.0f)?0.0f:(d/mx);
#elif SVAR==4
  sv_s = (mx==mn)?0.0f:(d/mx);
#elif SVAR==5
  sv_s = (mx==0.0f)?-0.0f:(d/mx);
#elif SVAR==6
  sv_s = d/mx;
#elif SVAR==7
  sv_s = (mx==0.0f)?0.0f:(1.0f-mn/mx);
#elif SVAR==8
  sv_s = (mx==0.0f)?0.0f:((mx-mn)/mx);
#endif
  // CMYK
  float k=1.0f-mx, c,m,y;
  if(k==1.0f){ c=0.0f;m=0.0f;y=0.0f; }
  else { c=(1.0f-r-k)/(1.0f-k); m=(1.0f-g-k)/(1.0f-k); y=(1.0f-b-k)/(1.0f-k); }
  // YUV
  float yy=((0.299f*r)+(0.587f*g))+(0.114f*b);
  float uu=((-0.147f*r)-(0.289f*g))+(0.436f*b);
  float vv=((0.615f*r)-(0.515f*g))-(0.100f*b);
  std::cout << h << " " << sl_s << " " << sl_l << " "
            << h << " " << sv_s << " " << sv_v << " "
            << c << " " << m << " " << y << " " << k << " "
            << yy << " " << uu << " " << vv << std::endl;
  return 0;
}
