cat > /tmp/probe/hsv/hunt.cpp <<'EOF'
#include <cstdio>
#include <cstdint>
#include <cmath>
#include <cstring>
#include <random>
#include <algorithm>
#include <sstream>
#include <iostream>
using namespace std;
static string P(float x){ ostringstream o; o<<x; return o.str(); }
static string P(double x){ ostringstream o; o<<x; return o.str(); }
int main(int argc,char**argv){
  unsigned long long seed = strtoull(argv[1],0,10);
  long long N = atoll(argv[2]);
  mt19937_64 rng(seed);
  long long fa=0,fb=0,fc=0;
  for(long long it=0; it<N; it++){
    float v[3];
    for(int i=0;i<3;i++){
      for(;;){ uint32_t u=(uint32_t)rng(); float f; memcpy(&f,&u,4);
        if(std::isfinite(f) && (f==0.0f || fabsf(f)>=1.5e-38f) && fabsf(f)<=3e38f){ v[i]=f; break; } }
      if(rng()%2) v[i] = (float)((double)(rng()>>11)/9007199254740992.0*4.0-1.0);
    }
    float r=v[0],g=v[1],b=v[2];
    float mx=std::max(std::max(r,g),b), mn=std::min(std::min(r,g),b), d=mx-mn;
    if(mx==0.0f) continue;
    float s_div = d/mx;
    float s_rec = d*(1.0f/mx);
    float s_dbl = (float)((double)d/(double)mx);
    double s_alldbl = (double)d/(double)mx;
    string a=P(s_div), bb=P(s_rec), cc=P(s_dbl), dd=P(s_alldbl);
    if(a!=bb && fa<12){ fa++; printf("REC %.9g %.9g %.9g   div=%s rec=%s\n",r,g,b,a.c_str(),bb.c_str()); }
    if(a!=cc && fb<12){ fb++; printf("DBL %.9g %.9g %.9g   div=%s dblround=%s\n",r,g,b,a.c_str(),cc.c_str()); }
    if(a!=dd && fc<12){ fc++; printf("ALLD %.9g %.9g %.9g   div=%s alldouble=%s\n",r,g,b,a.c_str(),dd.c_str()); }
    if(fa>=12&&fb>=12&&fc>=12) break;
  }
  fprintf(stderr,"rec=%lld dbl=%lld alld=%lld\n",fa,fb,fc);
}
