use std::io::{self,BufRead,Write};
fn cmax(a:f32,b:f32)->f32{ if a<b {b} else {a} }
fn cmin(a:f32,b:f32)->f32{ if b<a {b} else {a} }
fn main(){ let si=io::stdin(); let so=io::stdout(); let mut o=io::BufWriter::new(so.lock());
 for l in si.lock().lines(){ let l=l.unwrap(); let mut it=l.split_whitespace();
  let p=|t:&str|->f32{ let t=t.trim(); if t.eq_ignore_ascii_case("nan")||t.eq_ignore_ascii_case("-nan"){ return f32::NAN }
    if t.eq_ignore_ascii_case("inf"){ return f32::INFINITY } if t.eq_ignore_ascii_case("-inf"){ return f32::NEG_INFINITY }
    t.parse::<f32>().unwrap() };
  let r=p(it.next().unwrap()); let g=p(it.next().unwrap()); let b=p(it.next().unwrap());
  let mx=cmax(cmax(r,g),b); let mn=cmin(cmin(r,g),b); let d=mx-mn;
  let v=mx; let s=if mx==0.0 {0.0} else {d/mx};
  writeln!(o,"{:08x} {:08x}", s.to_bits(), v.to_bits()).unwrap(); } }
