pub fn rgb_to_hsv_sv(r: f32, g: f32, b: f32) -> (f32, f32) {
    let max = max3(r, g, b);
    let min = min3(r, g, b);
    let delta = max - min;
    let v = max;
    let s = if max == 0.0 { 0.0 } else { delta / max };
    (s, v)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn s(r: f32, g: f32, b: f32) -> f32 { hsv_s(r, g, b) }
    fn v(r: f32, g: f32, b: f32) -> f32 { hsv_v(r, g, b) }

